const batch = [
  {no:'sw0102',name:'A-Wing Pilot',en:'A-Wing Pilots flew the Rebellion\'s fastest interceptors, designed to outmaneuver TIE Fighters and protect larger ships. This minifigure features the distinctive green flight suit with Rebel insignia, specialized helmet with enhanced targeting systems, and agile combat readiness. Released in 2013, A-Wing pilots represented speed and precision. Collectors value these elite pilots for their daring hit-and-run tactics at Endor. Their incredible velocity made them perfect for rapid strike missions and escort duties. Essential for Rebel starfighter diversity and high-speed chase recreations.',de:'A-Flügelpiloten flogen die schnellsten Abfangjäger der Rebellion, entworfen um TIE-Jäger zu überflügeln und größere Schiffe zu schützen. Diese Minifigur zeigt den charakteristischen grünen Fluganzug mit Rebellenabzeichen, spezialisierten Helm mit verbesserten Zielsystemen und agiler Kampfbereitschaft. 2013 veröffentlicht, repräsentierten A-Flügelpiloten Geschwindigkeit und Präzision. Sammler schätzen diese Elite-Piloten für ihre gewagten Hit-and-Run-Taktiken bei Endor. Ihre unglaubliche Geschwindigkeit machte sie perfekt für schnelle Angriffsmissionen und Eskorte-Aufgaben. Unverzichtbar für Rebellen-Sternenjäger-Diversität und Hochgeschwindigkeits-Verfolgungsjagd-Nachstellungen.',fr:'Les Pilotes A-Wing pilotaient les intercepteurs les plus rapides de la Rébellion, conçus pour surpasser les TIE Fighters et protéger les navires plus grands. Cette minifigurine présente la combinaison de vol verte distinctive avec insigne Rebelle, casque spécialisé avec systèmes de ciblage améliorés et agilité de combat. Sortis en 2013, les pilotes A-Wing représentaient vitesse et précision. Les collectionneurs apprécient ces pilotes d\'élite pour leurs tactiques audacieuses de frappe et fuite à Endor. Leur vélocité incroyable les rendait parfaits pour des missions de frappe rapide et des tâches d\'escorte. Essentiels pour la diversité des chasseurs stellaires Rebelles et les recréations de poursuites à haute vitesse.',es:'Los Pilotos Ala-A volaron los interceptores más rápidos de la Rebelión, diseñados para superar a los Cazas TIE y proteger naves más grandes. Esta minifigura presenta el distintivo traje de vuelo verde con insignia Rebelde, casco especializado con sistemas de puntería mejorados y agilidad lista para combate. Lanzados en 2013, los pilotos Ala-A representaron velocidad y precisión. Los coleccionistas valoran estos pilotos de élite por sus audaces tácticas de golpear y huir en Endor. Su increíble velocidad los hizo perfectos para misiones de ataque rápido y deberes de escolta. Esenciales para diversidad de cazas estelares Rebeldes y recreaciones de persecuciones de alta velocidad.'},
  {no:'sw0103',name:'Y-Wing Pilot',en:'Y-Wing Pilots flew the Rebellion\'s workhorse bombers, delivering devastating ordnance against Imperial targets. This minifigure features the gray flight suit with yellow accents, specialized helmet with targeting computer interface, and determined bomber crew appearance. Released in 2007, Y-Wing pilots represented the Rebellion\'s heavy strike capability. Collectors appreciate these pilots for their crucial role at Yavin and Endor. The Y-Wing\'s ion cannons and proton torpedoes made them versatile attackers. Essential for Gold Squadron displays and torpedo run recreations.',de:'Y-Flügelpiloten flogen die Arbeitspferd-Bomber der Rebellion und lieferten verheerende Feuerkraft gegen imperiale Ziele. Diese Minifigur zeigt den grauen Fluganzug mit gelben Akzenten, spezialisierten Helm mit Zielcomputer-Interface und entschlossenes Bomberbesatzungs-Aussehen. 2007 veröffentlicht, repräsentierten Y-Flügelpiloten die schwere Angriffsfähigkeit der Rebellion. Sammler schätzen diese Piloten für ihre entscheidende Rolle bei Yavin und Endor. Die Ionenkanonen und Protonentorpedos des Y-Flügels machten sie zu vielseitigen Angreifern. Unverzichtbar für Gold-Squadron-Displays und Torpedo-Lauf-Nachstellungen.',fr:'Les Pilotes Y-Wing pilotaient les bombardiers de travail de la Rébellion, délivrant des munitions dévastatrices contre les cibles Impériales. Cette minifigurine présente la combinaison de vol grise avec accents jaunes, casque spécialisé avec interface informatique de ciblage et apparence déterminée d\'équipage de bombardier. Sortis en 2007, les pilotes Y-Wing représentaient la capacité de frappe lourde de la Rébellion. Les collectionneurs apprécient ces pilotes pour leur rôle crucial à Yavin et Endor. Les canons ioniques et torpilles à protons du Y-Wing en faisaient des attaquants polyvalents. Essentiels pour les expositions de l\'Escadron Gold et les recréations de courses de torpilles.',es:'Los Pilotos Ala-Y volaron los bombarderos de trabajo de la Rebelión, entregando munición devastadora contra objetivos Imperiales. Esta minifigura presenta el traje de vuelo gris con acentos amarillos, casco especializado con interfaz de computadora de puntería y apariencia determinada de tripulación de bombardero. Lanzados en 2007, los pilotos Ala-Y representaron la capacidad de ataque pesado de la Rebelión. Los coleccionistas aprecian estos pilotos por su papel crucial en Yavin y Endor. Los cañones iónicos y torpedos de protones del Ala-Y los hicieron atacantes versátiles. Esenciales para exhibiciones del Escuadrón Gold y recreaciones de carreras de torpedos.'},
  {no:'sw0104',name:'Ewok Warrior',en:'Ewok Warriors defended their forest home on Endor, helping the Rebels defeat Imperial forces with primitive yet effective tactics. This minifigure features brown fur texture, tribal hood, spear or bow weapon, and fierce determination. Released in 2002, Ewoks brought charm and combat prowess to the Battle of Endor. Collectors value these warriors for their crucial role in the ground assault. Their guerrilla tactics and knowledge of Endor\'s forests proved decisive. Essential for Endor forest battles, AT-ST takedowns, and village celebration scenes.',de:'Ewok-Krieger verteidigten ihre Waldheimat auf Endor und halfen den Rebellen, imperiale Streitkräfte mit primitiven aber effektiven Taktiken zu besiegen. Diese Minifigur zeigt braune Felltextur, Stammeskapuze, Speer- oder Bogenwaffe und heftige Entschlossenheit. 2002 veröffentlicht, brachten Ewoks Charme und Kampffähigkeit zur Schlacht um Endor. Sammler schätzen diese Krieger für ihre entscheidende Rolle im Bodenangriff. Ihre Guerilla-Taktiken und Kenntnis von Endors Wäldern erwiesen sich als entscheidend. Unverzichtbar für Endor-Waldschlachten, AT-ST-Übernahmen und Dorf-Feier-Szenen.',fr:'Les Guerriers Ewoks défendaient leur maison forestière sur Endor, aidant les Rebelles à vaincre les forces Impériales avec des tactiques primitives mais efficaces. Cette minifigurine présente une texture de fourrure brune, une capuche tribale, une arme lance ou arc et une détermination féroce. Sortis en 2002, les Ewoks ont apporté charme et prouesses au combat à la Bataille d\'Endor. Les collectionneurs apprécient ces guerriers pour leur rôle crucial dans l\'assaut au sol. Leurs tactiques de guérilla et connaissance des forêts d\'Endor se sont révélées décisives. Essentiels pour les batailles forestières d\'Endor, les démolitions d\'AT-ST et les scènes de célébration au village.',es:'Los Guerreros Ewok defendieron su hogar boscoso en Endor, ayudando a los Rebeldes a derrotar fuerzas Imperiales con tácticas primitivas pero efectivas. Esta minifigura presenta textura de pelaje marrón, capucha tribal, arma de lanza o arco y feroz determinación. Lanzados en 2002, los Ewoks trajeron encanto y destreza en combate a la Batalla de Endor. Los coleccionistas valoran estos guerreros por su papel crucial en el asalto terrestre. Sus tácticas de guerrilla y conocimiento de los bosques de Endor resultaron decisivos. Esenciales para batallas forestales de Endor, derribos de AT-ST y escenas de celebración en aldea.'},
  {no:'sw0105',name:'Wicket',en:'Wicket W. Warrick, the brave young Ewok who befriended Princess Leia, became a hero during the Battle of Endor. This minifigure features Wicket\'s distinctive brown and tan fur, tribal hood, spear, and curious friendly expression. Released in 2009, Wicket represents the heart of Ewok culture. Collectors treasure this character for discovering Leia and rallying his tribe against the Empire. His courage despite small size inspired the Rebellion. Essential for Endor forest encounters, Leia rescue scenes, and Ewok village displays celebrating the Empire\'s defeat.',de:'Wicket W. Warrick, der tapfere junge Ewok, der sich mit Prinzessin Leia anfreundete, wurde ein Held während der Schlacht um Endor. Diese Minifigur zeigt Wickets charakteristisches braun-beiges Fell, Stammeskapuze, Speer und neugierig-freundlichen Ausdruck. 2009 veröffentlicht, repräsentiert Wicket das Herz der Ewok-Kultur. Sammler schätzen diesen Charakter für die Entdeckung Leias und Sammeln seines Stammes gegen das Imperium. Sein Mut trotz kleiner Größe inspirierte die Rebellion. Unverzichtbar für Endor-Waldbegegnungen, Leia-Rettungsszenen und Ewok-Dorf-Displays, die die Niederlage des Imperiums feiern.',fr:'Wicket W. Warrick, le courageux jeune Ewok qui s\'est lié d\'amitié avec la Princesse Leia, est devenu un héros pendant la Bataille d\'Endor. Cette minifigurine présente la fourrure brune et beige distinctive de Wicket, une capuche tribale, une lance et une expression curieuse et amicale. Sortie en 2009, Wicket représente le cœur de la culture Ewok. Les collectionneurs apprécient ce personnage pour avoir découvert Leia et rallié sa tribu contre l\'Empire. Son courage malgré sa petite taille a inspiré la Rébellion. Essentiel pour les rencontres forestières d\'Endor, les scènes de sauvetage de Leia et les expositions de village Ewok célébrant la défaite de l\'Empire.',es:'Wicket W. Warrick, el valiente joven Ewok que se hizo amigo de la Princesa Leia, se convirtió en héroe durante la Batalla de Endor. Esta minifigura presenta el distintivo pelaje marrón y beige de Wicket, capucha tribal, lanza y expresión curiosa y amigable. Lanzado en 2009, Wicket representa el corazón de la cultura Ewok. Los coleccionistas atesoran este personaje por descubrir a Leia y reunir a su tribu contra el Imperio. Su coraje a pesar de su pequeño tamaño inspiró a la Rebelión. Esencial para encuentros forestales de Endor, escenas de rescate de Leia y exhibiciones de aldea Ewok celebrando la derrota del Imperio.'},
  {no:'sw0106',name:'Logray',en:'Logray served as the Ewok shaman and spiritual leader, initially planning to cook the Rebel heroes before C-3PO\'s divine intervention. This minifigure features Logray\'s distinctive headdress with animal skulls, striped fur hood, staff, and mystical appearance. Released in 2013, he represents Ewok religious traditions. Collectors appreciate Logray for his transformation from threatening cook to Rebel ally. His blessing of the attack on the shield generator proved crucial. Essential for Ewok village ceremonial scenes and the moment C-3PO became a golden god.',de:'Logray diente als Ewok-Schamane und spiritueller Führer und plante zunächst, die Rebellen-Helden zu kochen, bevor C-3POs göttliche Intervention kam. Diese Minifigur zeigt Lograys charakteristischen Kopfschmuck mit Tierschädeln, gestreifte Fellkapuze, Stab und mystisches Aussehen. 2013 veröffentlicht, repräsentiert er religiöse Ewok-Traditionen. Sammler schätzen Logray für seine Verwandlung vom bedrohlichen Koch zum Rebellen-Verbündeten. Sein Segen des Angriffs auf den Schildgenerator erwies sich als entscheidend. Unverzichtbar für Ewok-Dorf-Zeremonie-Szenen und den Moment, als C-3PO ein goldener Gott wurde.',fr:'Logray servait de chaman Ewok et chef spirituel, prévoyant initialement de cuisiner les héros Rebelles avant l\'intervention divine de C-3PO. Cette minifigurine présente la coiffe distinctive de Logray avec crânes d\'animaux, capuche de fourrure rayée, bâton et apparence mystique. Sortie en 2013, il représente les traditions religieuses Ewok. Les collectionneurs apprécient Logray pour sa transformation de cuisinier menaçant en allié Rebelle. Sa bénédiction de l\'attaque sur le générateur de bouclier s\'est révélée cruciale. Essentiel pour les scènes cérémonielles du village Ewok et le moment où C-3PO est devenu un dieu doré.',es:'Logray sirvió como chamán Ewok y líder espiritual, planeando inicialmente cocinar a los héroes Rebeldes antes de la intervención divina de C-3PO. Esta minifigura presenta el distintivo tocado de Logray con cráneos de animales, capucha de pelaje rayado, bastón y apariencia mística. Lanzado en 2013, representa tradiciones religiosas Ewok. Los coleccionistas aprecian a Logray por su transformación de cocinero amenazante a aliado Rebelde. Su bendición del ataque al generador de escudos resultó crucial. Esencial para escenas ceremoniales de aldea Ewok y el momento en que C-3PO se convirtió en un dios dorado.'},
  {no:'sw0107',name:'Chief Chirpa',en:'Chief Chirpa led the Ewok tribe on Endor with wisdom and courage, ultimately aiding the Rebellion against the Empire. This minifigure features Chirpa\'s distinctive gray fur, elaborate headdress with animal hide, staff of leadership, and dignified bearing. Released in 2013, he represents Ewok tribal authority. Collectors value Chief Chirpa for authorizing the attack on the Imperial bunker and rallying his warriors. His decision to trust the Rebels changed galactic history. Essential for Ewok council scenes and the ceremonial alliance between primitive and technological civilizations.',de:'Häuptling Chirpa führte den Ewok-Stamm auf Endor mit Weisheit und Mut und half letztendlich der Rebellion gegen das Imperium. Diese Minifigur zeigt Chirpas charakteristisches graues Fell, aufwendigen Kopfschmuck mit Tierfell, Führungsstab und würdevolles Auftreten. 2013 veröffentlicht, repräsentiert er tribale Ewok-Autorität. Sammler schätzen Häuptling Chirpa für die Autorisierung des Angriffs auf den imperialen Bunker und Sammeln seiner Krieger. Seine Entscheidung, den Rebellen zu vertrauen, änderte die galaktische Geschichte. Unverzichtbar für Ewok-Rats-Szenen und die zeremonielle Allianz zwischen primitiven und technologischen Zivilisationen.',fr:'Le Chef Chirpa dirigeait la tribu Ewok sur Endor avec sagesse et courage, aidant finalement la Rébellion contre l\'Empire. Cette minifigurine présente la fourrure grise distinctive de Chirpa, une coiffe élaborée avec peau d\'animal, un bâton de leadership et un maintien digne. Sortie en 2013, il représente l\'autorité tribale Ewok. Les collectionneurs apprécient le Chef Chirpa pour avoir autorisé l\'attaque sur le bunker Impérial et rallié ses guerriers. Sa décision de faire confiance aux Rebelles a changé l\'histoire galactique. Essentiel pour les scènes de conseil Ewok et l\'alliance cérémonielle entre civilisations primitive et technologique.',es:'El Jefe Chirpa lideró la tribu Ewok en Endor con sabiduría y coraje, finalmente ayudando a la Rebelión contra el Imperio. Esta minifigura presenta el distintivo pelaje gris de Chirpa, elaborado tocado con piel animal, bastón de liderazgo y porte digno. Lanzado en 2013, representa la autoridad tribal Ewok. Los coleccionistas valoran al Jefe Chirpa por autorizar el ataque al búnker Imperial y reunir a sus guerreros. Su decisión de confiar en los Rebeldes cambió la historia galáctica. Esencial para escenas de consejo Ewok y la alianza ceremonial entre civilizaciones primitiva y tecnológica.'},
  {no:'sw0108',name:'Scout Trooper',en:'Scout Troopers patrolled the forests of Endor on speeder bikes, providing reconnaissance for the Empire. This minifigure features distinctive white armor with black accents optimized for forest operations, specialized helmet with enhanced optics, and blaster pistol. Released in 2000, Scout Troopers became iconic for their speeder bike chase scenes. Collectors highly value these troopers for the thrilling pursuit through Endor\'s trees. Their lighter armor traded protection for speed and maneuverability. Essential for speeder bike displays and forest patrol scenes.',de:'Kundschafter-Truppen patrouillierten die Wälder von Endor auf Schwebegleitern und lieferten Aufklärung für das Imperium. Diese Minifigur zeigt charakteristische weiße Rüstung mit schwarzen Akzenten, optimiert für Waldoperationen, spezialisierten Helm mit verbesserter Optik und Blasterpistole. 2000 veröffentlicht, wurden Kundschafter-Truppen ikonisch für ihre Schwebegleiter-Verfolgungsszenen. Sammler schätzen diese Truppen sehr für die aufregende Verfolgungsjagd durch Endors Bäume. Ihre leichtere Rüstung tauschte Schutz gegen Geschwindigkeit und Manövrierfähigkeit. Unverzichtbar für Schwebegleiter-Displays und Wald-Patrouille-Szenen.',fr:'Les Soldats Éclaireurs patrouillaient les forêts d\'Endor sur des speeder bikes, fournissant de la reconnaissance pour l\'Empire. Cette minifigurine présente une armure blanche distinctive avec accents noirs optimisée pour les opérations forestières, un casque spécialisé avec optiques améliorées et un pistolet blaster. Sortis en 2000, les Soldats Éclaireurs sont devenus emblématiques pour leurs scènes de poursuite en speeder bike. Les collectionneurs apprécient grandement ces soldats pour la poursuite palpitante à travers les arbres d\'Endor. Leur armure plus légère échangeait protection contre vitesse et maniabilité. Essentiels pour les expositions de speeder bikes et les scènes de patrouille forestière.',es:'Los Soldados Exploradores patrullaron los bosques de Endor en motos deslizadoras, proporcionando reconocimiento para el Imperio. Esta minifigura presenta distintiva armadura blanca con acentos negros optimizada para operaciones forestales, casco especializado con ópticas mejoradas y pistola bláster. Lanzados en 2000, los Soldados Exploradores se volvieron icónicos por sus escenas de persecución en moto deslizadora. Los coleccionistas valoran mucho estos soldados por la emocionante persecución a través de los árboles de Endor. Su armadura más ligera intercambió protección por velocidad y maniobrabilidad. Esenciales para exhibiciones de motos deslizadoras y escenas de patrulla forestal.'},
  {no:'sw0109',name:'Royal Guard',en:'Royal Guards protected Emperor Palpatine with fanatical loyalty and deadly combat skills. This minifigure features the iconic crimson robes and armor, face-concealing helmet, force pike weapon, and imposing silent presence. Released in 2001, Royal Guards embodied Imperial elite security. Collectors prize these guards for their mysterious nature and unwavering devotion to the Emperor. Their rare appearances made each sighting significant. Essential for Imperial throne room scenes, Death Star II displays, and showcasing the Empire\'s most elite protectors.',de:'Königliche Wachen schützten Imperator Palpatine mit fanatischer Loyalität und tödlichen Kampffähigkeiten. Diese Minifigur zeigt die ikonischen purpurroten Roben und Rüstung, gesichtsverhüllenden Helm, Macht-Piken-Waffe und imposante stille Präsenz. 2001 veröffentlicht, verkörperten Königliche Wachen imperiale Elite-Sicherheit. Sammler schätzen diese Wachen für ihre mysteriöse Natur und unerschütterliche Hingabe zum Imperator. Ihre seltenen Auftritte machten jede Sichtung bedeutsam. Unverzichtbar für imperiale Thronsaal-Szenen, Todesstern-II-Displays und Darstellung der elitärsten Beschützer des Imperiums.',fr:'Les Gardes Royaux protégeaient l\'Empereur Palpatine avec une loyauté fanatique et des compétences de combat mortelles. Cette minifigurine présente les robes et armure cramoisies emblématiques, un casque dissimulant le visage, une arme pique de force et une présence silencieuse imposante. Sortis en 2001, les Gardes Royaux incarnaient la sécurité d\'élite Impériale. Les collectionneurs apprécient ces gardes pour leur nature mystérieuse et leur dévouement inébranlable à l\'Empereur. Leurs apparitions rares rendaient chaque observation significative. Essentiels pour les scènes de salle du trône Impériale, les expositions de l\'Étoile de la Mort II et présenter les protecteurs les plus d\'élite de l\'Empire.',es:'Los Guardias Reales protegieron al Emperador Palpatine con lealtad fanática y habilidades de combate mortales. Esta minifigura presenta las icónicas túnicas y armadura carmesí, casco que oculta el rostro, arma pica de fuerza y presencia silenciosa imponente. Lanzados en 2001, los Guardias Reales encarnaron la seguridad de élite Imperial. Los coleccionistas valoran estos guardias por su naturaleza misteriosa y devoción inquebrantable al Emperador. Sus raras apariciones hicieron cada avistamiento significativo. Esenciales para escenas de sala del trono Imperial, exhibiciones de Estrella de la Muerte II y mostrar los protectores más élite del Imperio.'},
  {no:'sw0110',name:'AT-ST Driver',en:'AT-ST Drivers piloted the Empire\'s two-legged scout walkers through hostile terrain. This minifigure features distinctive gray uniform with armor vest, specialized helmet with targeting systems, and military bearing. Released in 2007, AT-ST drivers represented Imperial armored vehicle crews. Collectors value these pilots for operating the intimidating chicken walkers on Endor and Hoth. Their tactical vulnerability to Ewok traps became legendary. Essential for AT-ST cockpits, Endor forest patrols, and displays showing the walkers\' strengths and weaknesses.',de:'AT-ST-Fahrer steuerten die zweibeinigen Kundschafter-Läufer des Imperiums durch feindliches Gelände. Diese Minifigur zeigt charakteristische graue Uniform mit Rüstungsweste, spezialisierten Helm mit Zielsystemen und militärische Haltung. 2007 veröffentlicht, repräsentierten AT-ST-Fahrer imperiale gepanzerte Fahrzeugbesatzungen. Sammler schätzen diese Piloten für das Bedienen der einschüchternden Hühner-Läufer auf Endor und Hoth. Ihre taktische Verwundbarkeit gegenüber Ewok-Fallen wurde legendär. Unverzichtbar für AT-ST-Cockpits, Endor-Wald-Patrouillen und Displays, die die Stärken und Schwächen der Läufer zeigen.',fr:'Les Pilotes AT-ST pilotaient les marcheurs éclaireurs à deux jambes de l\'Empire à travers un terrain hostile. Cette minifigurine présente un uniforme gris distinctif avec gilet blindé, un casque spécialisé avec systèmes de ciblage et un maintien militaire. Sortis en 2007, les pilotes AT-ST représentaient les équipages de véhicules blindés Impériaux. Les collectionneurs apprécient ces pilotes pour opérer les intimidants marcheurs poulets sur Endor et Hoth. Leur vulnérabilité tactique aux pièges Ewok est devenue légendaire. Essentiels pour les cockpits AT-ST, les patrouilles forestières d\'Endor et les expositions montrant les forces et faiblesses des marcheurs.',es:'Los Conductores AT-ST pilotaron los caminantes exploradores de dos patas del Imperio a través de terreno hostil. Esta minifigura presenta distintivo uniforme gris con chaleco blindado, casco especializado con sistemas de puntería y porte militar. Lanzados en 2007, los conductores AT-ST representaron tripulaciones de vehículos blindados Imperiales. Los coleccionistas valoran estos pilotos por operar los intimidantes caminantes gallina en Endor y Hoth. Su vulnerabilidad táctica a las trampas Ewok se volvió legendaria. Esenciales para cabinas AT-ST, patrullas forestales de Endor y exhibiciones mostrando las fortalezas y debilidades de los caminantes.'},
  {no:'sw0111',name:'AT-AT Driver',en:'AT-AT Drivers commanded the Empire\'s massive assault walkers, piloting terror weapons across battlefields. This minifigure features light gray uniform with black accents, specialized helmet with enhanced visor, and cockpit crew appearance. Released in 2003, AT-AT drivers represented elite Imperial armor commanders. Collectors value these pilots for the iconic Hoth battle and devastating firepower. Their towering walkers dominated landscapes until Rebel ingenuity brought them down. Essential for AT-AT cockpit displays and Battle of Hoth recreations showing Imperial military might.',de:'AT-AT-Fahrer kommandierten die massiven Angriffs-Läufer des Imperiums und steuerten Terrorwaffen über Schlachtfelder. Diese Minifigur zeigt hellgraue Uniform mit schwarzen Akzenten, spezialisierten Helm mit verbessertem Visier und Cockpit-Besatzungs-Aussehen. 2003 veröffentlicht, repräsentierten AT-AT-Fahrer elite imperiale Panzer-Kommandeure. Sammler schätzen diese Piloten für die ikonische Hoth-Schlacht und verheerende Feuerkraft. Ihre turmhohen Läufer dominierten Landschaften, bis Rebellen-Einfallsreichtum sie zu Fall brachte. Unverzichtbar für AT-AT-Cockpit-Displays und Schlacht-um-Hoth-Nachstellungen, die imperiale militärische Macht zeigen.',fr:'Les Pilotes AT-AT commandaient les massifs marcheurs d\'assaut de l\'Empire, pilotant des armes de terreur à travers les champs de bataille. Cette minifigurine présente un uniforme gris clair avec accents noirs, un casque spécialisé avec visière améliorée et une apparence d\'équipage de cockpit. Sortis en 2003, les pilotes AT-AT représentaient les commandants d\'armure d\'élite Impériaux. Les collectionneurs apprécient ces pilotes pour la bataille emblématique de Hoth et la puissance de feu dévastatrice. Leurs marcheurs imposants dominaient les paysages jusqu\'à ce que l\'ingéniosité Rebelle les abatte. Essentiels pour les expositions de cockpit AT-AT et les recréations de Bataille de Hoth montrant la puissance militaire Impériale.',es:'Los Conductores AT-AT comandaron los masivos caminantes de asalto del Imperio, pilotando armas de terror por campos de batalla. Esta minifigura presenta uniforme gris claro con acentos negros, casco especializado con visor mejorado y apariencia de tripulación de cabina. Lanzados en 2003, los conductores AT-AT representaron comandantes de armadura de élite Imperiales. Los coleccionistas valoran estos pilotos por la icónica batalla de Hoth y poder de fuego devastador. Sus imponentes caminantes dominaron paisajes hasta que la ingenuidad Rebelde los derribó. Esenciales para exhibiciones de cabina AT-AT y recreaciones de Batalla de Hoth mostrando poderío militar Imperial.'},
  {no:'sw0112',name:'Snowtrooper',en:'Snowtroopers specialized in cold weather operations, deploying on ice planets like Hoth to crush Rebel resistance. This minifigure features distinctive white armor with insulated fabric underlayer, cold weather helmet with breath mask, backpack with heating systems, and E-11 blaster. Released in 2003, Snowtroopers defined the Hoth assault. Collectors value these specialized troopers for their role in overrunning Echo Base. Their environmental adaptation showcased Imperial military versatility. Essential for Hoth trenches, Echo Base infiltration, and winter warfare displays.',de:'Schneetruppen spezialisierten sich auf Kaltwetter-Operationen und wurden auf Eisplaneten wie Hoth eingesetzt, um Rebellenwiderstand zu zerschlagen. Diese Minifigur zeigt charakteristische weiße Rüstung mit isolierter Stoffunterlage, Kaltwetter-Helm mit Atemmaske, Rucksack mit Heizsystemen und E-11-Blaster. 2003 veröffentlicht, definierten Schneetruppen den Hoth-Angriff. Sammler schätzen diese spezialisierten Truppen für ihre Rolle bei der Überrumpelung der Echo-Basis. Ihre Umweltanpassung zeigte imperiale militärische Vielseitigkeit. Unverzichtbar für Hoth-Schützengräben, Echo-Basis-Infiltration und Winterkriegs-Displays.',fr:'Les Snowtroopers se spécialisaient dans les opérations par temps froid, se déployant sur des planètes glacées comme Hoth pour écraser la résistance Rebelle. Cette minifigurine présente une armure blanche distinctive avec sous-couche de tissu isolé, un casque de temps froid avec masque respiratoire, un sac à dos avec systèmes de chauffage et un blaster E-11. Sortis en 2003, les Snowtroopers ont défini l\'assaut de Hoth. Les collectionneurs apprécient ces soldats spécialisés pour leur rôle dans l\'envahissement de la Base Echo. Leur adaptation environnementale a montré la polyvalence militaire Impériale. Essentiels pour les tranchées de Hoth, l\'infiltration de la Base Echo et les expositions de guerre hivernale.',es:'Los Snowtroopers se especializaron en operaciones de clima frío, desplegando en planetas helados como Hoth para aplastar la resistencia Rebelde. Esta minifigura presenta distintiva armadura blanca con capa inferior de tela aislada, casco de clima frío con máscara respiratoria, mochila con sistemas de calefacción y bláster E-11. Lanzados en 2003, los Snowtroopers definieron el asalto de Hoth. Los coleccionistas valoran estos soldados especializados por su papel en invadir la Base Echo. Su adaptación ambiental mostró la versatilidad militar Imperial. Esenciales para trincheras de Hoth, infiltración de Base Echo y exhibiciones de guerra invernal.'},
  {no:'sw0113',name:'Hoth Rebel Trooper',en:'Hoth Rebel Troopers defended Echo Base against the Empire\'s overwhelming assault on the ice planet. This minifigure features tan and white cold weather gear with goggles, insulated parka, communication equipment, and blaster rifle. Released in 2004, these troopers represented the Rebellion\'s desperate stand. Collectors value these soldiers for manning the trenches during the Battle of Hoth. Their brave defense bought time for the evacuation. Essential for Echo Base defenses, trench warfare scenes, and displaying Rebel winter combat readiness.',de:'Hoth-Rebellen-Truppen verteidigten die Echo-Basis gegen den überwältigenden Angriff des Imperiums auf dem Eisplaneten. Diese Minifigur zeigt beige-weiße Kaltwetter-Ausrüstung mit Schutzbrille, isolierte Parka, Kommunikationsausrüstung und Blastergewehr. 2004 veröffentlicht, repräsentierten diese Truppen den verzweifelten Stand der Rebellion. Sammler schätzen diese Soldaten für die Besetzung der Schützengräben während der Schlacht um Hoth. Ihre tapfere Verteidigung gewann Zeit für die Evakuierung. Unverzichtbar für Echo-Basis-Verteidigung, Schützengraben-Kriegs-Szenen und Darstellung der Rebellen-Winterkampf-Bereitschaft.',fr:'Les Soldats Rebelles de Hoth défendaient la Base Echo contre l\'assaut écrasant de l\'Empire sur la planète de glace. Cette minifigurine présente un équipement de temps froid beige et blanc avec lunettes, parka isolée, équipement de communication et fusil blaster. Sortis en 2004, ces soldats représentaient la résistance désespérée de la Rébellion. Les collectionneurs apprécient ces soldats pour avoir tenu les tranchées pendant la Bataille de Hoth. Leur défense courageuse a gagné du temps pour l\'évacuation. Essentiels pour les défenses de la Base Echo, les scènes de guerre de tranchées et présenter la préparation au combat hivernal Rebelle.',es:'Los Soldados Rebeldes de Hoth defendieron la Base Echo contra el abrumador asalto del Imperio en el planeta helado. Esta minifigura presenta equipo de clima frío beige y blanco con gafas, parka aislada, equipo de comunicación y rifle bláster. Lanzados en 2004, estos soldados representaron la desesperada resistencia de la Rebelión. Los coleccionistas valoran estos soldados por tripular las trincheras durante la Batalla de Hoth. Su valiente defensa ganó tiempo para la evacuación. Esenciales para defensas de Base Echo, escenas de guerra de trincheras y mostrar preparación de combate invernal Rebelde.'},
  {no:'sw0114',name:'Snowspeeder Pilot',en:'Snowspeeder Pilots flew modified airspeeders in daring attacks against AT-AT walkers during the Battle of Hoth. This minifigure features orange flight suit adapted for cold weather, insulated helmet with visor, survival equipment, and Rebel insignia. Released in 2003, these pilots became heroes for their tow cable tactics. Collectors highly value Snowspeeder pilots for the iconic AT-AT takedown sequences. Their ingenuity and bravery saved countless Rebel lives. Essential for Snowspeeder cockpits, Hoth aerial combat, and the legendary walker tripping scenes.',de:'Schneegleiter-Piloten flogen modifizierte Luftgleiter in gewagten Angriffen gegen AT-AT-Läufer während der Schlacht um Hoth. Diese Minifigur zeigt orangefarbenen Fluganzug, angepasst für kaltes Wetter, isolierten Helm mit Visier, Überlebensausrüstung und Rebellenabzeichen. 2003 veröffentlicht, wurden diese Piloten Helden für ihre Abschleppseil-Taktiken. Sammler schätzen Schneegleiter-Piloten sehr für die ikonischen AT-AT-Übernahme-Sequenzen. Ihr Einfallsreichtum und Mut retteten unzählige Rebellenleben. Unverzichtbar für Schneegleiter-Cockpits, Hoth-Luftkampf und die legendären Läufer-Stolper-Szenen.',fr:'Les Pilotes de Snowspeeder volaient des aéroglisseurs modifiés dans des attaques audacieuses contre les marcheurs AT-AT pendant la Bataille de Hoth. Cette minifigurine présente une combinaison de vol orange adaptée au temps froid, un casque isolé avec visière, un équipement de survie et un insigne Rebelle. Sortis en 2003, ces pilotes sont devenus des héros pour leurs tactiques de câble de remorquage. Les collectionneurs apprécient grandement les pilotes de Snowspeeder pour les séquences emblématiques de démolition d\'AT-AT. Leur ingéniosité et bravoure ont sauvé d\'innombrables vies Rebelles. Essentiels pour les cockpits de Snowspeeder, le combat aérien de Hoth et les scènes légendaires de trébuchement de marcheurs.',es:'Los Pilotos de Snowspeeder volaron aerodeslizadores modificados en atrevidos ataques contra caminantes AT-AT durante la Batalla de Hoth. Esta minifigura presenta traje de vuelo naranja adaptado para clima frío, casco aislado con visor, equipo de supervivencia e insignia Rebelde. Lanzados en 2003, estos pilotos se convirtieron en héroes por sus tácticas de cable de remolque. Los coleccionistas valoran mucho a los pilotos de Snowspeeder por las icónicas secuencias de derribo de AT-AT. Su ingenio y valentía salvaron incontables vidas Rebeldes. Esenciales para cabinas de Snowspeeder, combate aéreo de Hoth y las legendarias escenas de tropiezo de caminantes.'},
  {no:'sw0115',name:'General Veers',en:'General Maximilian Veers commanded Imperial ground forces, personally leading the assault on Hoth from his AT-AT. This minifigure features gray Imperial officer uniform with rank insignia, combat helmet, stern military bearing, and tactical brilliance. Released in 2010, Veers represents Imperial ground warfare excellence. Collectors prize this figure for his professional competence and ruthless efficiency destroying the shield generator. His leadership nearly crushed the Rebellion at Echo Base. Essential for AT-AT command displays and Hoth battle strategy scenes.',de:'General Maximilian Veers kommandierte imperiale Bodentruppen und führte persönlich den Angriff auf Hoth von seinem AT-AT aus an. Diese Minifigur zeigt graue imperiale Offiziersuniform mit Rangabzeichen, Kampfhelm, strenge militärische Haltung und taktische Brillanz. 2010 veröffentlicht, repräsentiert Veers imperiale Bodenkriegs-Exzellenz. Sammler schätzen diese Figur für seine professionelle Kompetenz und rücksichtslose Effizienz bei der Zerstörung des Schildgenerators. Seine Führung zerschlug die Rebellion bei der Echo-Basis fast. Unverzichtbar für AT-AT-Kommando-Displays und Hoth-Schlacht-Strategie-Szenen.',fr:'Le Général Maximilian Veers commandait les forces terrestres Impériales, menant personnellement l\'assaut sur Hoth depuis son AT-AT. Cette minifigurine présente un uniforme d\'officier Impérial gris avec insignes de rang, un casque de combat, un maintien militaire sévère et une brillance tactique. Sortie en 2010, Veers représente l\'excellence de la guerre terrestre Impériale. Les collectionneurs apprécient cette figurine pour sa compétence professionnelle et son efficacité impitoyable détruisant le générateur de bouclier. Son leadership a presque écrasé la Rébellion à la Base Echo. Essentielle pour les expositions de commandement AT-AT et les scènes de stratégie de bataille de Hoth.',es:'El General Maximilian Veers comandó fuerzas terrestres Imperiales, liderando personalmente el asalto en Hoth desde su AT-AT. Esta minifigura presenta uniforme de oficial Imperial gris con insignias de rango, casco de combate, severo porte militar y brillantez táctica. Lanzado en 2010, Veers representa la excelencia en guerra terrestre Imperial. Los coleccionistas valoran esta figura por su competencia profesional y eficiencia despiadada destruyendo el generador de escudos. Su liderazgo casi aplastó a la Rebelión en Base Echo. Esencial para exhibiciones de comando AT-AT y escenas de estrategia de batalla de Hoth.'},
  {no:'sw0116',name:'Luke Skywalker (Hoth)',en:'Luke Skywalker on Hoth survived wampa attack and led the Snowspeeder assault against AT-AT walkers. This minifigure features tan cold weather flight suit, insulated jacket, pilot helmet, and lightsaber. Released in 2004, Hoth Luke shows his growth as both pilot and Jedi. Collectors value this variant for the wampa cave escape and ingenious walker takedown. His Force abilities saved him from freezing. Essential for Echo Base displays, wampa cave scenes, and the legendary tow cable attack.',de:'Luke Skywalker auf Hoth überlebte Wampa-Angriff und führte den Schneegleiter-Angriff gegen AT-AT-Läufer an. Diese Minifigur zeigt beigen Kaltwetter-Fluganzug, isolierte Jacke, Pilotenhelm und Lichtschwert. 2004 veröffentlicht, zeigt Hoth-Luke sein Wachstum als Pilot und Jedi. Sammler schätzen diese Variante für die Wampa-Höhlen-Flucht und geniale Läufer-Übernahme. Seine Macht-Fähigkeiten retteten ihn vor dem Erfrieren. Unverzichtbar für Echo-Basis-Displays, Wampa-Höhlen-Szenen und den legendären Abschleppseil-Angriff.',fr:'Luke Skywalker sur Hoth a survécu à l\'attaque du wampa et a mené l\'assaut en Snowspeeder contre les marcheurs AT-AT. Cette minifigurine présente une combinaison de vol de temps froid beige, une veste isolée, un casque de pilote et un sabre laser. Sortie en 2004, Luke de Hoth montre sa croissance en tant que pilote et Jedi. Les collectionneurs apprécient cette variante pour l\'évasion de la grotte du wampa et la démolition ingénieuse du marcheur. Ses capacités de Force l\'ont sauvé du gel. Essentielle pour les expositions de la Base Echo, les scènes de grotte du wampa et l\'attaque légendaire au câble de remorquage.',es:'Luke Skywalker en Hoth sobrevivió el ataque wampa y lideró el asalto Snowspeeder contra caminantes AT-AT. Esta minifigura presenta traje de vuelo de clima frío beige, chaqueta aislada, casco de piloto y sable de luz. Lanzado en 2004, Luke de Hoth muestra su crecimiento como piloto y Jedi. Los coleccionistas valoran esta variante por el escape de cueva wampa y el ingenioso derribo de caminante. Sus habilidades de la Fuerza lo salvaron de congelarse. Esencial para exhibiciones de Base Echo, escenas de cueva wampa y el legendario ataque de cable de remolque.'},
  {no:'sw0117',name:'Han Solo (Hoth)',en:'Han Solo on Hoth commanded Rebel defenses and rescued Luke from freezing on the ice plains. This minifigure features tan Hoth parka with hood, cold weather gear, blue pants, and blaster pistol. Released in 2003, Hoth Han showcases his leadership and devotion to Luke. Collectors treasure this variant for the tauntaun rescue and "I thought they smelled bad on the outside" moment. His quick thinking saved Luke\'s life. Essential for Echo Base command centers, tauntaun patrol scenes, and the iconic shelter-building survival sequence.',de:'Han Solo auf Hoth kommandierte Rebellen-Verteidigung und rettete Luke vor dem Erfrieren auf den Eisebenen. Diese Minifigur zeigt beige Hoth-Parka mit Kapuze, Kaltwetter-Ausrüstung, blaue Hose und Blasterpistole. 2003 veröffentlicht, zeigt Hoth-Han seine Führung und Hingabe zu Luke. Sammler schätzen diese Variante für die Tauntaun-Rettung und "Ich dachte, sie riechen von außen schlecht"-Moment. Sein schnelles Denken rettete Lukes Leben. Unverzichtbar für Echo-Basis-Kommandozentralen, Tauntaun-Patrouille-Szenen und die ikonische Unterschlupf-Bau-Überlebenssequenz.',fr:'Han Solo sur Hoth commandait les défenses Rebelles et a sauvé Luke du gel sur les plaines glacées. Cette minifigurine présente une parka Hoth beige avec capuche, un équipement de temps froid, un pantalon bleu et un pistolet blaster. Sortie en 2003, Han de Hoth montre son leadership et sa dévotion à Luke. Les collectionneurs apprécient cette variante pour le sauvetage en tauntaun et le moment "Je pensais qu\'ils sentaient mauvais à l\'extérieur". Sa réflexion rapide a sauvé la vie de Luke. Essentielle pour les centres de commandement de la Base Echo, les scènes de patrouille en tauntaun et la séquence de survie emblématique de construction d\'abri.',es:'Han Solo en Hoth comandó las defensas Rebeldes y rescató a Luke de congelarse en las llanuras heladas. Esta minifigura presenta parka Hoth beige con capucha, equipo de clima frío, pantalones azules y pistola bláster. Lanzado en 2003, Han de Hoth muestra su liderazgo y devoción a Luke. Los coleccionistas atesoran esta variante por el rescate en tauntaun y el momento "Pensé que olían mal por fuera". Su rápido pensamiento salvó la vida de Luke. Esencial para centros de comando de Base Echo, escenas de patrulla en tauntaun y la icónica secuencia de supervivencia construyendo refugio.'},
  {no:'sw0118',name:'Princess Leia (Hoth)',en:'Princess Leia on Hoth commanded the evacuation of Echo Base while coordinating Rebel military operations. This minifigure features white cold weather command uniform with vest, insulated jacket, communication equipment, and leadership presence. Released in 2011, Hoth Leia demonstrates her military command abilities. Collectors value this variant for her tactical decisions during the Imperial assault. Her calm under pressure saved the Rebellion. Essential for Echo Base command center displays and evacuation coordination scenes showing Leia\'s leadership.',de:'Prinzessin Leia auf Hoth kommandierte die Evakuierung der Echo-Basis während sie rebelli militärische Operationen koordinierte. Diese Minifigur zeigt weiße Kaltwetter-Kommando-Uniform mit Weste, isolierte Jacke, Kommunikationsausrüstung und Führungspräsenz. 2011 veröffentlicht, demonstriert Hoth-Leia ihre militärischen Kommandofähigkeiten. Sammler schätzen diese Variante für ihre taktischen Entscheidungen während des imperialen Angriffs. Ihre Ruhe unter Druck rettete die Rebellion. Unverzichtbar für Echo-Basis-Kommandozentralen-Displays und Evakuierungs-Koordinations-Szenen, die Leias Führung zeigen.',fr:'La Princesse Leia sur Hoth commandait l\'évacuation de la Base Echo tout en coordonnant les opérations militaires Rebelles. Cette minifigurine présente un uniforme de commandement de temps froid blanc avec gilet, veste isolée, équipement de communication et présence de leadership. Sortie en 2011, Leia de Hoth démontre ses capacités de commandement militaire. Les collectionneurs apprécient cette variante pour ses décisions tactiques pendant l\'assaut Impérial. Son calme sous pression a sauvé la Rébellion. Essentielle pour les expositions de centre de commandement de la Base Echo et les scènes de coordination d\'évacuation montrant le leadership de Leia.',es:'La Princesa Leia en Hoth comandó la evacuación de la Base Echo mientras coordinaba operaciones militares Rebeldes. Esta minifigura presenta uniforme de comando de clima frío blanco con chaleco, chaqueta aislada, equipo de comunicación y presencia de liderazgo. Lanzada en 2011, Leia de Hoth demuestra sus habilidades de comando militar. Los coleccionistas valoran esta variante por sus decisiones tácticas durante el asalto Imperial. Su calma bajo presión salvó a la Rebelión. Esencial para exhibiciones de centro de comando de Base Echo y escenas de coordinación de evacuación mostrando el liderazgo de Leia.'},
  {no:'sw0119',name:'Tauntaun',en:'Tauntauns served as the primary mounted transportation for Rebels patrolling Hoth\'s frozen wastes. This brick-built creature features gray-white fur texture, curved horns, reptilian face, saddle mount, and hardy ice planet adaptation. Released in 2003, tauntauns brought Hoth\'s ecosystem to life. Collectors treasure these creatures for patrol scenes and Luke\'s emergency shelter. Their unfortunate smell became legendary. Essential for Hoth wilderness displays, patrol missions, and the desperate moment Han used one to save Luke\'s life.',de:'Tauntauns dienten als primäres berittenes Transportmittel für Rebellen, die Hoths gefrorene Einöden patrouillierten. Diese aus Steinen gebaute Kreatur zeigt grau-weiße Felltextur, gebogene Hörner, reptilienartiges Gesicht, Sattelhalterung und robuste Eisplaneten-Anpassung. 2003 veröffentlicht, brachten Tauntauns Hoths Ökosystem zum Leben. Sammler schätzen diese Kreaturen für Patrouille-Szenen und Lukes Notunterkunft. Ihr unglücklicher Geruch wurde legendär. Unverzichtbar für Hoth-Wildnis-Displays, Patrouille-Missionen und den verzweifelten Moment, als Han einen benutzte, um Lukes Leben zu retten.',fr:'Les Tauntauns servaient de transport monté principal pour les Rebelles patrouillant les étendues gelées de Hoth. Cette créature construite en briques présente une texture de fourrure gris-blanc, des cornes courbées, un visage reptilien, une monture de selle et une adaptation robuste à la planète de glace. Sortis en 2003, les tauntauns ont donné vie à l\'écosystème de Hoth. Les collectionneurs apprécient ces créatures pour les scènes de patrouille et l\'abri d\'urgence de Luke. Leur odeur malheureuse est devenue légendaire. Essentiels pour les expositions de nature sauvage de Hoth, les missions de patrouille et le moment désespéré où Han en a utilisé un pour sauver la vie de Luke.',es:'Los Tauntauns sirvieron como transporte montado principal para Rebeldes patrullando los yermos congelados de Hoth. Esta criatura construida con ladrillos presenta textura de pelaje gris-blanco, cuernos curvos, rostro reptiliano, montura de silla y robusta adaptación de planeta helado. Lanzados en 2003, los tauntauns dieron vida al ecosistema de Hoth. Los coleccionistas atesoran estas criaturas por escenas de patrulla y refugio de emergencia de Luke. Su desafortunado olor se volvió legendario. Esenciales para exhibiciones de desierto de Hoth, misiones de patrulla y el momento desesperado en que Han usó uno para salvar la vida de Luke.'},
  {no:'sw0120',name:'Wampa',en:'The Wampa ice creature of Hoth nearly killed Luke Skywalker in its frozen cave lair. This brick-built beast features white fur, massive claws, fanged mouth, imposing size, and predatory ferocity. Released in 2011, the Wampa brought Hoth\'s apex predator to terrifying life. Collectors highly prize this creature for the iconic cave attack scene. Luke\'s lightsaber arm severance established these beasts\' lethality. Essential for wampa cave displays, Hoth wildlife exhibits, and Luke\'s harrowing survival ordeal.',de:'Die Wampa-Eiskreatur von Hoth tötete Luke Skywalker in ihrer gefrorenen Höhle fast. Dieses aus Steinen gebaute Biest zeigt weißes Fell, massive Klauen, Fangmaul, imposante Größe und räuberische Wildheit. 2011 veröffentlicht, brachte der Wampa Hoths Spitzenräuber zum erschreckenden Leben. Sammler schätzen diese Kreatur sehr für die ikonische Höhlen-Angriffsszene. Lukes Lichtschwert-Arm-Abtrennung etablierte die Tödlichkeit dieser Bestien. Unverzichtbar für Wampa-Höhlen-Displays, Hoth-Wildlife-Ausstellungen und Lukes schreckliche Überlebens-Tortur.',fr:'La créature de glace Wampa de Hoth a failli tuer Luke Skywalker dans son antre de grotte gelée. Cette bête construite en briques présente une fourrure blanche, des griffes massives, une gueule à crocs, une taille imposante et une férocité prédatrice. Sortie en 2011, le Wampa a donné vie au prédateur apex terrifiant de Hoth. Les collectionneurs apprécient grandement cette créature pour la scène d\'attaque de grotte emblématique. La section du bras au sabre laser de Luke a établi la létalité de ces bêtes. Essentielle pour les expositions de grotte de wampa, les expositions de faune de Hoth et l\'épreuve de survie déchirante de Luke.',es:'La criatura de hielo Wampa de Hoth casi mata a Luke Skywalker en su guarida de cueva congelada. Esta bestia construida con ladrillos presenta pelaje blanco, garras masivas, boca con colmillos, tamaño imponente y ferocidad depredadora. Lanzado en 2011, el Wampa dio vida al depredador ápice aterrador de Hoth. Los coleccionistas valoran mucho esta criatura por la icónica escena de ataque de cueva. La amputación del brazo con sable de luz de Luke estableció la letalidad de estas bestias. Esencial para exhibiciones de cueva wampa, exhibiciones de vida silvestre de Hoth y la desgarradora prueba de supervivencia de Luke.'},
  {no:'sw0121',name:'Probe Droid',en:'Imperial Probe Droids scoured the galaxy searching for hidden Rebel bases, discovering Echo Base on Hoth. This brick-built droid features black spherical body with multiple sensor arms, photoreceptors, repulsorlift system, and self-destruct mechanism. Released in 2003, probe droids represented Imperial reconnaissance technology. Collectors value these droids for their eerie presence and discovery of the Rebellion. Their methodical search patterns made them nearly unstoppable. Essential for Hoth ice plains, Imperial intelligence operations, and Han Solo\'s futile attempt to capture one.',de:'Imperiale Sondendroiden durchsuchten die Galaxis auf der Suche nach versteckten Rebellenbasen und entdeckten die Echo-Basis auf Hoth. Dieser aus Steinen gebaute Droide zeigt schwarzen kugelförmigen Körper mit mehreren Sensorarmen, Fotorezeptoren, Repulsor-Lift-System und Selbstzerstörungsmechanismus. 2003 veröffentlicht, repräsentierten Sondendroiden imperiale Aufklärungstechnologie. Sammler schätzen diese Droiden für ihre unheimliche Präsenz und Entdeckung der Rebellion. Ihre methodischen Suchmuster machten sie nahezu unaufhaltsam. Unverzichtbar für Hoth-Eisebenen, imperiale Geheimdienstoperationen und Han Solos vergeblichen Versuch, einen zu fangen.',fr:'Les Droïdes Sondes Impériaux parcouraient la galaxie à la recherche de bases Rebelles cachées, découvrant la Base Echo sur Hoth. Ce droïde construit en briques présente un corps sphérique noir avec plusieurs bras de capteurs, des photorécepteurs, un système de répulseur et un mécanisme d\'autodestruction. Sortis en 2003, les droïdes sondes représentaient la technologie de reconnaissance Impériale. Les collectionneurs apprécient ces droïdes pour leur présence inquiétante et leur découverte de la Rébellion. Leurs schémas de recherche méthodiques les rendaient presque inarrêtables. Essentiels pour les plaines glacées de Hoth, les opérations de renseignement Impérial et la tentative futile de Han Solo d\'en capturer un.',es:'Los Droides Sonda Imperiales recorrieron la galaxia buscando bases Rebeldes ocultas, descubriendo la Base Echo en Hoth. Este droide construido con ladrillos presenta cuerpo esférico negro con múltiples brazos de sensor, fotorreceptores, sistema de repulsor y mecanismo de autodestrucción. Lanzados en 2003, los droides sonda representaron tecnología de reconocimiento Imperial. Los coleccionistas valoran estos droides por su presencia inquietante y descubrimiento de la Rebelión. Sus patrones de búsqueda metódicos los hicieron casi imparables. Esenciales para llanuras heladas de Hoth, operaciones de inteligencia Imperial y el intento fútil de Han Solo de capturar uno.'}
];

async function save() {
  console.log('💾 Batches 23-25 (sw0102-sw0121)...\n');
  for (const m of batch) {
    await prisma.minifigCatalog.upsert({
      where: { minifigure_no: m.no },
      update: {
        description_en: m.en, description_de: m.de, description_fr: m.fr, description_es: m.es,
        description_generated_at: new Date(), description_status: 'generated'
      },
      create: {
        minifigure_no: m.no, name: m.name, category_id: 1, category_name: 'Star Wars',
        search_name: m.name.toLowerCase(), description_en: m.en, description_de: m.de,
        description_fr: m.fr, description_es: m.es, description_generated_at: new Date(),
        description_status: 'generated'
      }
    });
    console.log(`  ✅ ${m.no}`);
  }
  console.log('\n✨ 120 total (480 descriptions)\n');
  await prisma.$disconnect();
}

save().catch(console.error);
